    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_fraction = step_index as f64 / total_jobs as f64;
    let dynamic_factor = 1.0 + (step_fraction * 0.5); // Adjust factor based on step

    // Lookahead awareness for next job
    let next_job_norm_cpu = next_job_cpu as f64 / node_capacity_cpu as f64;
    let next_job_norm_ram = next_job_ram as f64 / node_capacity_ram as f64;

    // Non-linear conditionals and lookahead packing bonuses
    let packing_bonus = if next_job_cpu <= node_residual_cpu && next_job_ram <= node_residual_ram {
        0.2 * (node_residual_cpu - next_job_cpu) as f64 + 0.2 * (node_residual_ram - next_job_ram) as f64
    } else {
        0.0
    };

    // Imbalance penalties and horizon-aware placement logic
    let penalized_imbalance = imbalance_penalty * dynamic_factor;
    let node_usage_ratio = (node_capacity_cpu + node_capacity_ram) as f64 / (2.0 * active_nodes_count as f64);
    let penalty_factor = if node_usage_ratio > 1.5 {
        1.5
    } else {
        1.0
    };

    let score = (cpu_norm + ram_norm) / 2.0 + penalized_imbalance * penalty_factor + packing_bonus;
    score
}

